INSERT INTO `packages` VALUES (1,'SITE_SINGLE','Vé lẻ 1 điểm','Single site pass','Nghe trọn thuyết minh 1 địa điểm và các điểm nhấn trong 24 giờ.','Full narration of one site and its highlights for 24 hours.',29000,'site',24,1,1,NULL,NULL,1),(2,'ALL_DAY','Vé ngày – Toàn vịnh','Day pass – Whole bay','Mở khoá toàn bộ địa điểm và điểm nhấn trong 24 giờ, kèm bản đồ GPS tự động.','Unlock every site and highlight for 24 hours, with automatic GPS narration.',99000,'all',24,1,1,'Phổ biến nhất','Most popular',2),(3,'FAMILY','Gói gia đình','Family pack','Toàn bộ địa điểm cho tối đa 4 người trong 48 giờ.','All sites for up to 4 people for 48 hours.',199000,'all',48,4,1,'Tiết kiệm','Best value',3);
