  `package_name` varchar(255) NOT NULL,
  `site_id` int(11) DEFAULT NULL,
  `amount` int(11) NOT NULL,
  `method` varchar(16) NOT NULL,
  `status` varchar(16) NOT NULL,
  `visitor_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `lang` varchar(8) DEFAULT NULL,
  `customer_name` varchar(120) DEFAULT NULL,
  `customer_phone` varchar(32) DEFAULT NULL,
  `created_at` varchar(32) NOT NULL,
  `created_ms` bigint(20) NOT NULL,
  `paid_at` varchar(32) DEFAULT NULL,
  `paid_ms` bigint(20) DEFAULT NULL,
  `expires_at` varchar(32) NOT NULL,
  `transfer_note` varchar(64) NOT NULL,
  `demo` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_orders_created` (`created_ms`),
  KEY `idx_orders_paid` (`status`,`paid_ms`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
